repo.bookings.py:
"""Booking records."""


class Booking:
    def __init__(self, hotel, nights):
        self.hotel = hotel
        self.nights = nights

    def __repr__(self):
        return "Booking(%r, %r)" % (self.hotel, self.nights)


ROWS = [('harbour', 24), ('plaza', 14), ('grand', 4), ('harbour', 18), ('lodge', 23), ('lodge', 12), ('grand', 50)]


def load_bookings():
    """Yield the stored bookings one at a time."""
    for hotel, nights in ROWS:
        yield Booking(hotel, nights)

repo.portion.py:
"""Percentages of the total nights."""


def percent_of_total(bookings, hotel):
    """Return the percentage, from 0 to 100, of the total nights that belongs to this hotel."""
    total = sum(x.nights for x in bookings)
    part = sum(x.nights for x in bookings if x.hotel == hotel)
    return part // total * 100


def total_nights(bookings):
    """Return the total nights."""
    return sum(x.nights for x in bookings)


def describe_booking(booking):
    """Return a one-line description of a booking."""
    return "%s: %s" % (booking.hotel, booking.nights)
